SELECT V.TRADE_DATE AS `交易日期`, A.CSNAME AS `股票名称`, A.COMB_SYMBOL AS `股票代码`, ROUND(V.OPEN_PRICE, 2) AS `开盘价(美元)`, ROUND(V.HIGH_PRICE, 2) AS `最高价(美元)`, ROUND(V.LOW_PRICE, 2) AS `最低价(美元)`, ROUND(V.CLOSE_PRICE, 2) AS `收盘价(美元)`, ROUND(V.TRADE_AMOUNT / 100000000, 2) AS `成交额(亿美元)`, ROUND(V.TOTAL_SHARES / 100000000, 2) AS `总股本(亿股)` FROM AMERICAN_STOCK_MAIN A INNER JOIN VIEW_US_EOD_EXPR V ON A.FIU_ID = V.FIU_ID WHERE A.CSNAME LIKE '%微软%' AND V.TRADE_DATE = '2026-08-25' AND V.CLOSE_PRICE IS NOT NULL AND V.OPEN_PRICE IS NOT NULL AND V.HIGH_PRICE IS NOT NULL AND V.LOW_PRICE IS NOT NULL AND V.TRADE_AMOUNT IS NOT NULL AND V.TOTAL_SHARES IS NOT NULL;
